        const s = sa + 4 + k * 5.2;
        const [px, pz] = atS(s, lat + 24 + row * 7);
        if (lakeSD(px, pz) < 6 || clearance(px, pz) < 5) continue;
        const cc = carCols[Math.floor(R() * carCols.length)];
