        const logA = [0.5, 0.33, 0.19], logB = [0.43, 0.28, 0.16], y0 = yf + 3.42, h = 2.7, ov = 0.75, rfA = [0.2, 0.38, 0.28], rfB = [0.17, 0.33, 0.24], stC = [0.52, 0.5, 0.47], trim = [0.84, 0.79, 0.66], glass = [0.16, 0.2, 0.25];
