          if (d < m.fl + 5) { m.st = 1; m.fx = m.bx; m.fy = m.by; m.fz = m.bz; m.tS = T0 + 0.4; } else if (m.tS > m.pk) { m.st = 4; m.tS = 0; }   // (a car again: straight back down)
