    { const [a, b] = AT.amb; rect(a, b, 512, 64, '#f4f4f2'); rect(a, b + 4, 512, 6, '#d8261e'); rect(a, b + 54, 512, 6, '#d8261e'); txt('RACE RESCUE', a + 256, b + 33, 40, '#d8261e', 480); }
