    const carCols = [[0.92, 0.92, 0.9], [0.7, 0.72, 0.74], [0.16, 0.16, 0.18], [0.62, 0.12, 0.1], [0.16, 0.3, 0.55], [0.85, 0.85, 0.82], [0.32, 0.34, 0.36]];
