      const [px, pz, ii] = onSide(s, side, side > 0 && dropAt(T.idx(s), 1) ? -0.5 : 0.9); if (excluded(px, pz)) return;
      const py = unGround(px, pz), [v0, v1, u0, u1] = board(k); box(scen.get(px, pz), px, py - 0.2, pz, 0.1, hgt + 0.2, 0.1, T.hd[ii], [0.6, 0.61, 0.63]);
