      const i = T.idx(s), x = T.px[i], z = T.pz[i], y = T.hy[i], nx = T.nx[i], nz = T.nz[i], L1 = Math.min(T.bl[i] - 0.3, w + 1.4) + 0.3, L2 = Math.min(T.br[i] - 0.3, w + 1.4) + 0.3, g = scen.get(x, z), hd = T.hd[i];
