      for (const sd of [-1, 1]) { run(sStart - 70, sStart + 70, sd, { rows: 3, dens: 0.6, label: 'BT start' }); run(sFin - 70, sFin + 14, sd, { rows: 3, dens: 0.6, label: 'BT finish' }); }
