        if (inCorr(x, z) || inCorr(x - 50, z) || inCorr(x + 50, z) || inCorr(x, z - 50) || inCorr(x, z + 50)) y -= 45;
        if (behind(x, z)) y = Math.min(y, TMC.y - 80);
