      for (let n = 0; n < 60 && T.k[(a - 1 + N) % N] < -1 / 70; n++) a = (a - 1 + N) % N;
      for (let n = 0; n < 60 && T.k[(b + 1) % N] < -1 / 70; n++) b = (b + 1) % N;
